cat > /tmp/resolve.sql <<'SQL'
INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
LOAD httpfs;
CREATE OR REPLACE MACRO car() AS TABLE
  SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');

.print '=== P1 point (-51.391, -15.540) as lon-lat -> containing GO parcel ==='
