WHERE cod_estado='GO'
  AND bbox.xmin<=-51.39127228109898 AND bbox.xmax>=-51.39127228109898
  AND bbox.ymin<=-15.539711049431583 AND bbox.ymax>=-15.539711049431583
  AND ST_Contains(ST_MakeValid(geometry), ST_Point(-51.39127228109898,-15.539711049431583));

.print '=== P4 point (-35,-10) -> containing parcel (expect none) ==='
SELECT count(*) n FROM car()
WHERE bbox.xmin<=-35 AND bbox.xmax>=-35 AND bbox.ymin<=-10 AND bbox.ymax>=-10
  AND ST_Contains(ST_MakeValid(geometry), ST_Point(-35,-10));
