cat > /tmp/idjoin.sql <<'SQL'
INSTALL httpfs; LOAD httpfs;
CREATE TABLE lst AS SELECT * FROM read_csv_auto('/workspace/lists/goias-sample.csv', header=true, all_varchar=true);
CREATE TABLE ids AS SELECT DISTINCT cod_imovel FROM lst WHERE cod_imovel IS NOT NULL AND cod_imovel<>'';
CREATE OR REPLACE MACRO car() AS TABLE
  SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');
-- CAR rows for the listed ids only
CREATE TABLE carhit AS
  SELECT c.cod_imovel, c.municipio, c.num_area
  FROM car() c JOIN ids USING (cod_imovel);
.print '=== distinct listed ids ==='
SELECT count(*) FROM ids;
.print '=== distinct listed ids found in CAR ==='
SELECT count(DISTINCT cod_imovel) FROM carhit;
.print '=== listed ids MISSING from CAR ==='
SELECT count(*) FROM ids WHERE cod_imovel NOT IN (SELECT cod_imovel FROM carhit);
.print '=== q07a: listed ids with >1 CAR row ==='
SELECT count(*) FROM (SELECT cod_imovel FROM carhit GROUP BY cod_imovel HAVING count(*)>1);
.print '=== q07b: distinct listed parcels with num_area<1 ==='
SELECT count(DISTINCT cod_imovel) FROM carhit WHERE num_area < 1;
.print '=== do the 3 geometry-resolved parcels appear among listed ids? ==='
SELECT cod_imovel, (cod_imovel IN (SELECT cod_imovel FROM ids)) AS in_list
FROM (VALUES
 ('GO-5212204-15108D4D7C134B8D9E71E50A2ED2E605'),
 ('GO-5212204-6A28AC5AF7BF4BEC8931E8E154D99AEE'),
 ('GO-5212204-F17BEA20B17148C1ADB4BD53A04EC448')) t(cod_imovel);
SQL
time timeout 600 duckdb -bail < /tmp/idjoin.sql 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | head -60

cat > /tmp/env.sql <<'SQL'
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
CREATE TABLE lst AS SELECT * FROM read_csv_auto('/workspace/lists/goias-sample.csv', header=true, all_varchar=true);
CREATE TABLE ids AS SELECT DISTINCT cod_imovel FROM lst WHERE cod_imovel IS NOT NULL AND cod_imovel<>'';
-- resolved parcels = listed ids + 3 geometry-resolved
CREATE TABLE resolved AS
  SELECT cod_imovel FROM ids
  UNION
  SELECT * FROM (VALUES
   ('GO-5212204-15108D4D7C134B8D9E71E50A2ED2E605'),
   ('GO-5212204-6A28AC5AF7BF4BEC8931E8E154D99AEE'),
   ('GO-5212204-F17BEA20B17148C1ADB4BD53A04EC448')) t(cod_imovel);
CREATE OR REPLACE MACRO car() AS TABLE
  SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');
CREATE TABLE carres AS
  SELECT c.cod_imovel, c.municipio, c.num_area, c.bbox
  FROM car() c JOIN resolved r USING (cod_imovel);
.print '=== count resolved parcels joined ==='
SELECT count(*) FROM carres;
.print '=== q06 parcels per municipio ==='
SELECT municipio, count(DISTINCT cod_imovel) AS n_parcels FROM carres GROUP BY municipio ORDER BY n_parcels DESC, municipio;
.print '=== envelope of resolved parcels ==='
SELECT min(bbox.xmin) xmin, min(bbox.ymin) ymin, max(bbox.xmax) xmax, max(bbox.ymax) ymax FROM carres;
SQL
time timeout 600 duckdb -bail < /tmp/env.sql 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | head -40
